RANGES = {131:(1,24),132:(25,30),133:(31,37),134:(38,48),135:(49,56),136:(57,62),137:(63,77)}
UNIT_RANGES = {1:(1,24),2:(25,30),3:(31,37),4:(38,48),5:(49,56),6:(57,62),7:(63,77)}
for u in UNITS:
    s,e = UNIT_RANGES[u["n"]]
    u["qs"] = [f"PEDS-C16-{i:03d}" for i in range(s,e+1)]

pages = [q["page"] for q in QUESTIONS]
assert pages == sorted(pages), f"Pages not sorted {pages[:10]}"
assert len(QUESTIONS)==77
assert len(UNITS)==7
for u in UNITS:
    s,e = UNIT_RANGES[u["n"]]
    assert len(u["qs"])==e-s+1
